import java.util.Scanner;

public class I {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        double val = Double.parseDouble(scanner.next());
        long p = (long)(val * 10000);
        execute(n, p);
    }

    public static void execute(long n, long p) {
        long studied = 0;
        long notStudied = n;

        while (true) {
            long zero = notStudied * (notStudied - 1) * (notStudied - 2) / 6;
            long one = studied * notStudied * (notStudied - 1) / 2;
            long two = studied * (studied - 1) * notStudied / 2;
            long three = studied * (studied - 1) * (studied - 2) / 6;

            long sumP = zero * 0 + one * 1 + two * 2 + three * 2;
            long totalComb = n * (n - 1) * (n - 2) / 6;

            if (sumP * 5000 >= p * totalComb) {
                System.out.println(studied);
                return;
            }
            studied++;
            notStudied--;
        }
    }
}
